+describe("view_order_reversed", () => {
+    const reversed = (value: boolean) =>
+        OPTIONS_UPDATE({
+            view_order_reversed: { value } as any,
+        });
+
+    it("is read from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+        let s = reduceFlows(
+            defaultState,
+            OPTIONS_RECEIVE({
+                view_order_reversed: { value: true },
+            } as any),
+        );
+        expect(s.view_order_reversed).toBe(true);
+        s = reduceFlows(s, reversed(false));
+        expect(s.view_order_reversed).toBe(false);
+    });
+
+    it("inserts new flows at the front when set", () => {
+        const [a, b] = [TFlow(), TFlow()];
+        a.id = "a";
+        b.id = "b";
+        let s = reduceFlows(defaultState, reversed(true));
+        s = reduceFlows(
+            s,
+            flowActions.FLOWS_ADD({ flow: a, matching_filters: {} }),
+        );
+        s = reduceFlows(
+            s,
+            flowActions.FLOWS_ADD({ flow: b, matching_filters: {} }),
+        );
+        expect(s.view.map((f) => f.id)).toEqual(["b", "a"]);
+        expect(s.list.map((f) => f.id)).toEqual(["a", "b"]);
+        expect(s._viewIndex.get("b")).toBe(0);
+    });
+
+    it("appends new flows when not set", () => {
+        const [a, b] = [TFlow(), TFlow()];
+        a.id = "a";
+        b.id = "b";
+        let s = reduceFlows(defaultState, reversed(false));
+        s = reduceFlows(
+            s,
+            flowActions.FLOWS_ADD({ flow: a, matching_filters: {} }),
+        );
+        s = reduceFlows(
+            s,
+            flowActions.FLOWS_ADD({ flow: b, matching_filters: {} }),
+        );
+        expect(s.view.map((f) => f.id)).toEqual(["a", "b"]);
+    });
+
+    it("is overridden by an active column sort", () => {
+        const [a, b] = [TFlow(), TFlow()];
+        a.id = "a";
+        b.id = "b";
+        a.comment = "1";
+        b.comment = "2";
+        let s = reduceFlows(defaultState, reversed(true));
+        s = reduceFlows(
+            s,
+            flowActions.setSort({ column: "comment", desc: false }),
+        );
+        s = reduceFlows(
+            s,
+            flowActions.FLOWS_ADD({ flow: a, matching_filters: {} }),
+        );
+        s = reduceFlows(
+            s,
+            flowActions.FLOWS_ADD({ flow: b, matching_filters: {} }),
+        );
+        expect(s.view.map((f) => f.id)).toEqual(["a", "b"]);
+    });
+});
